#include <algorithm>
#include <cstdint>
#include <cstring>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <thread>
#include <vector>
#include <string>
#include <limits>

#include "stations.inc"

static constexpr int NST = 413;
static constexpr uint64_t FNV_OFFSET = 1469598103934665603ULL;
static constexpr uint64_t FNV_PRIME = 1099511628211ULL;

struct HashEntry {
    uint64_t hash;
    uint16_t len;
    uint16_t id;
};
static HashEntry table[1024];

static inline uint64_t name_hash(const char *p, size_t n) {
    uint64_t h = FNV_OFFSET;
    for (size_t i = 0; i < n; ++i) {
        h ^= static_cast<unsigned char>(p[i]);
        h *= FNV_PRIME;
    }
    return h;
}

static inline unsigned find_station(const char *p, size_t n, uint64_t h) {
    unsigned pos = static_cast<unsigned>(h) & 1023u;
    for (;;) {
        const HashEntry &e = table[pos];
        if (e.len == 0) return 0xffffu;
        if (e.hash == h && e.len == n && std::memcmp(p, station_names[e.id], n) == 0)
            return e.id;
        pos = (pos + 1) & 1023u;
    }
}

struct Stat {
    int mn;
    int mx;
    int64_t sum;
    uint64_t count;
};

struct Worker {
    const char *begin;
    const char *end;
    std::vector<Stat> stats;
    Worker(const char *b, const char *e) : begin(b), end(e), stats(NST) {
        for (Stat &s : stats) { s.mn = 1000; s.mx = -1000; s.sum = 0; s.count = 0; }
    }
    void operator()() {
        const char *p = begin;
        while (p < end) {
            const char *name = p;
            uint64_t h = FNV_OFFSET;
            while (*p != ';') {
                h ^= static_cast<unsigned char>(*p++);
                h *= FNV_PRIME;
            }
            unsigned id = find_station(name, static_cast<size_t>(p - name), h);
            const char *t = p + 1;
            bool neg = (*t == '-');
            t += neg;
            int v;
            if (t[1] == '.') {
                v = (t[0] - '0') * 10 + (t[2] - '0');
                t += 3;
            } else {
                v = (t[0] - '0') * 100 + (t[1] - '0') * 10 + (t[3] - '0');
                t += 4;
            }
            if (neg) v = -v;
            Stat &s = stats[id];
            if (v < s.mn) s.mn = v;
            if (v > s.mx) s.mx = v;
            s.sum += v;
            ++s.count;
            p = t + 1;
        }
    }
};

static inline void append_tenths(std::string &out, int64_t v) {
    if (v < 0) { out.push_back('-'); v = -v; }
    out += std::to_string(v / 10);
    out.push_back('.');
    out.push_back(static_cast<char>('0' + v % 10));
}

int main(int argc, char **argv) {
    if (argc != 2) return 2;
    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) return 2;
    struct stat st;
    if (fstat(fd, &st) != 0) return 2;
    size_t size = static_cast<size_t>(st.st_size);
    const char *data = static_cast<const char *>(mmap(nullptr, size, PROT_READ, MAP_PRIVATE, fd, 0));
    close(fd);
    if (data == MAP_FAILED) return 2;

    for (unsigned i = 0; i < 1024; ++i) table[i] = {0, 0, 0};
    for (unsigned i = 0; i < NST; ++i) {
        size_t n = std::strlen(station_names[i]);
        uint64_t h = name_hash(station_names[i], n);
        unsigned pos = static_cast<unsigned>(h) & 1023u;
        while (table[pos].len != 0) pos = (pos + 1) & 1023u;
        table[pos] = {h, static_cast<uint16_t>(n), static_cast<uint16_t>(i)};
    }

    constexpr unsigned T = 6;
    std::vector<size_t> bounds(T + 1);
    bounds[0] = 0;
    bounds[T] = size;
    for (unsigned i = 1; i < T; ++i) {
        size_t b = size * i / T;
        while (b < size && data[b - 1] != '\n') ++b;
        bounds[i] = b;
    }
    std::vector<Worker> workers;
    workers.reserve(T);
    for (unsigned i = 0; i < T; ++i)
        workers.emplace_back(data + bounds[i], data + bounds[i + 1]);
    std::vector<std::thread> threads;
    threads.reserve(T);
    for (Worker &w : workers) threads.emplace_back(std::ref(w));
    for (std::thread &t : threads) t.join();

    std::vector<Stat> all(NST);
    for (Stat &s : all) { s.mn = 1000; s.mx = -1000; s.sum = 0; s.count = 0; }
    for (const Worker &w : workers) {
        for (int i = 0; i < NST; ++i) {
            const Stat &a = w.stats[i];
            Stat &s = all[i];
            if (a.count) {
                if (a.mn < s.mn) s.mn = a.mn;
                if (a.mx > s.mx) s.mx = a.mx;
                s.sum += a.sum;
                s.count += a.count;
            }
        }
    }

    std::vector<int> order(NST);
    for (int i = 0; i < NST; ++i) order[i] = i;
    std::sort(order.begin(), order.end(), [](int a, int b) {
        return std::strcmp(station_names[a], station_names[b]) < 0;
    });
    std::string out;
    out.reserve(18000);
    out.push_back('{');
    for (int k = 0; k < NST; ++k) {
        if (k) out += ", ";
        int i = order[k];
        out += station_names[i];
        out.push_back('=');
        append_tenths(out, all[i].mn);
        out.push_back('/');
        int64_t mean;
        if (all[i].sum >= 0)
            mean = (all[i].sum + static_cast<int64_t>(all[i].count) / 2) / static_cast<int64_t>(all[i].count);
        else
            mean = -((-all[i].sum + static_cast<int64_t>(all[i].count) / 2) / static_cast<int64_t>(all[i].count));
        append_tenths(out, mean);
        out.push_back('/');
        append_tenths(out, all[i].mx);
    }
    out.push_back('}');
    size_t written = 0;
    while (written < out.size()) {
        ssize_t n = write(STDOUT_FILENO, out.data() + written, out.size() - written);
        if (n <= 0) break;
        written += static_cast<size_t>(n);
    }
    munmap(const_cast<char *>(data), size);
    return written == out.size() ? 0 : 2;
}

