edits.oldText:
static constexpr uint64_t FNV_OFFSET = 1469598103934665603ULL;
static constexpr uint64_t FNV_PRIME = 1099511628211ULL;

struct HashEntry {
    uint64_t hash;
    uint16_t len;
    uint16_t id;
};
static HashEntry table[1024];

static inline uint64_t name_hash(const char *p, size_t n) {
    uint64_t h = FNV_OFFSET;
    for (size_t i = 0; i < n; ++i) {
        h ^= static_cast<unsigned char>(p[i]);
        h *= FNV_PRIME;
    }
    return h;
}

static inline unsigned find_station(const char *p, size_t n, uint64_t h) {
    unsigned pos = static_cast<unsigned>(h) & 1023u;
    for (;;) {
        const HashEntry &e = table[pos];
        if (e.len == 0) return 0xffffu;
        if (e.hash == h && e.len == n && std::memcmp(p, station_names[e.id], n) == 0)
            return e.id;
        pos = (pos + 1) & 1023u;
    }
}

edits.newText:
struct PrefixEntry {
    uint32_t key;
    uint16_t start;
    uint16_t count;
};
static PrefixEntry prefix_table[1024];
static uint16_t prefix_ids[NST];
static uint16_t station_lengths[NST];

static inline uint32_t prefix_key(const char *p, size_t n) {
    uint32_t k = static_cast<unsigned char>(p[0]) |
                 (static_cast<uint32_t>(static_cast<unsigned char>(p[1])) << 8) |
                 (static_cast<uint32_t>(static_cast<unsigned char>(p[2])) << 16);
    if (n >= 4) k |= static_cast<uint32_t>(static_cast<unsigned char>(p[3])) << 24;
    return k;
}

static inline unsigned find_station(const char *p, size_t n, uint32_t key) {
    unsigned pos = (key * 2654435761u) >> 22;
    for (;;) {
        const PrefixEntry &e = prefix_table[pos];
        if (e.count == 0) return 0xffffu;
        if (e.key == key) {
            if (e.count == 1) return prefix_ids[e.start];
            for (unsigned j = 0; j < e.count; ++j) {
                unsigned id = prefix_ids[e.start + j];
                if (station_lengths[id] == n && std::memcmp(p, station_names[id], n) == 0)
                    return id;
            }
            return 0xffffu;
        }
        pos = (pos + 1) & 1023u;
    }
}

