        size_t b = size * i / T;
        while (b < size && data[b - 1] != '\n') ++b;
        bounds[i] = b;
    }
    std::vector<Worker> workers;
    workers.reserve(T);
    for (unsigned i = 0; i < T; ++i)
        workers.emplace_back(data + bounds[i], data + bounds[i + 1]);
