#include <algorithm>
#include <cstdint>
#include <cstring>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <thread>
#include <vector>
#include <string>
#include <limits>

#include "stations.inc"

static constexpr int NST = 413;
#ifndef NTHREADS
#define NTHREADS 6
#endif
static constexpr uint64_t FNV_OFFSET = 1469598103934665603ULL;
static constexpr uint64_t FNV_PRIME = 1099511628211ULL;

struct HashEntry {
    uint64_t hash;
    uint16_t len;
    uint16_t id;
};
static HashEntry table[1024];

static inline uint64_t name_hash(const char *p, size_t n) {
    uint64_t h = FNV_OFFSET;
    for (size_t i = 0; i < n; ++i) {
        h ^= static_cast<unsigned char>(p[i]);
        h *= FNV_PRIME;
    }
    return h;
}

static inline unsigned find_station(const char *p, size_t n, uint64_t h) {
    unsigned pos = static_cast<unsigned>(h) & 1023u;
    for (;;) {
        const HashEntry &e = table[pos];
        if (e.len == 0) return 0xffffu;
        if (e.hash == h && e.len == n && std::memcmp(p, station_names[e.id], n) == 0)
            return e.id;
        pos = (pos + 1) & 1023u;
    }
}

struct Stat {
    int mn;
    int mx;
    int64_t sum;
    uint64_t count;
};

struct Worker {
    const char *begin;
    const char *end;
    std::vector<Stat> stats;
    Worker(const char *b, const char *e) : begin(b), end(e), stats(NST) {
        for (Stat &s : stats) { s.mn = 1000; s.mx = -1000; s.sum = 0; s.count = 0; }
    }
    void operator()() {
        const char *p = begin;
        while (p < end) {
            const char *name = p;
            uint64_t h = FNV_OFFSET;
            while (*p != ';') {
                h ^= static_cast<unsigned char>(*p++);
                h *= FNV_PRIME;
            }
            unsigned id = find_station(name, static_cast<size_t>(p - name), h);
            const char *t = p + 1;
            bool neg = (*t == '-');
            t += neg;
            int v;
            if (t[1] == '.') {
                v = (t[0] - '0') * 10 + (t[2] - '0');
                t += 3;
            } else {
                v = (t[0] - '0') * 100 + (t[1] - '0') * 10 + (t[3] - '0');
                t += 4;
            }
            if (neg) v = -v;
            Stat &s = stats[id];
            if (v < s.mn) s.mn = v;
            if (v > s.mx) s.mx = v;
            s.sum += v;
            ++s.count;
            p = t + 1;
        }
    }
};

static inline void append_tenths(std::string &out, int64_t v) {
    if (v < 0) { out.push_back('-'); v = -v; }
    out += std::to_string(v / 10);
    out.push_back('.');
    out.push_back(static_cast<char>('0' + v % 10));
}

