#include <algorithm>
#include <immintrin.h>
#include <cstdint>
#include <cstring>
#include <fcntl.h>
#include <pthread.h>
#include <sched.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <thread>
#include <vector>
#include <string>
#include <limits>

#include "stations.inc"

static constexpr int NST = 413;
#ifndef NTHREADS
#define NTHREADS 6
#endif
static uint16_t ph_start[1024];
static uint8_t ph_count[1024];
static uint8_t ph_disp[512];
static uint16_t prefix_ids[NST];
static uint16_t station_lengths[NST];

static inline uint32_t prefix_key(const char *p, size_t n) {
    uint32_t k = static_cast<unsigned char>(p[0]) |
                 (static_cast<uint32_t>(static_cast<unsigned char>(p[1])) << 8) |
                 (static_cast<uint32_t>(static_cast<unsigned char>(p[2])) << 16);
    if (n >= 4) k |= static_cast<uint32_t>(static_cast<unsigned char>(p[3])) << 24;
    return k;
}

static inline unsigned find_station(const char *p, size_t n, uint32_t key) {
    unsigned bucket = key & 511u;
    unsigned pos = (((key * 2344817613u) >> 22) + ph_disp[bucket]) & 1023u;
    unsigned count = ph_count[pos];
    if (count == 1) return ph_start[pos];
    unsigned start = ph_start[pos];
    for (unsigned j = 0; j < count; ++j) {
        unsigned id = prefix_ids[start + j];
        if (station_lengths[id] == n && std::memcmp(p, station_names[id], n) == 0)
            return id;
    }
    return 0xffffu;
}

struct Stat {
    int mn;
    int mx;
    int64_t sum;
    uint64_t count;
};

struct Worker {
    const char *begin;
    const char *end;
    std::vector<Stat> stats;
    Worker(const char *b, const char *e) : begin(b), end(e), stats(NST) {
        for (Stat &s : stats) { s.mn = 1000; s.mx = -1000; s.sum = 0; s.count = 0; }
    }
    void operator()() {
        const char *p = begin;
        while (p < end) {
            const char *name = p;
            uint32_t first;
            __builtin_memcpy(&first, p, sizeof(first));
            uint32_t key = first;
            if ((first >> 24) == static_cast<unsigned>(';')) key &= 0x00ffffffu;
            const __m128i semi = _mm_set1_epi8(';');
            __m128i bytes = _mm_loadu_si128(reinterpret_cast<const __m128i *>(p));
            unsigned mask = static_cast<unsigned>(_mm_movemask_epi8(_mm_cmpeq_epi8(bytes, semi)));
            if (mask) {
                p += __builtin_ctz(mask);
            } else {
                bytes = _mm_loadu_si128(reinterpret_cast<const __m128i *>(p + 16));
                mask = static_cast<unsigned>(_mm_movemask_epi8(_mm_cmpeq_epi8(bytes, semi)));
                p += 16 + __builtin_ctz(mask);
            }
            unsigned id = find_station(name, static_cast<size_t>(p - name), key);
            const char *t = p + 1;
            bool neg = (*t == '-');
            t += neg;
            int v;
            if (t[1] == '.') {
                v = (t[0] - '0') * 10 + (t[2] - '0');
                t += 3;
            } else {
                v = (t[0] - '0') * 100 + (t[1] - '0') * 10 + (t[3] - '0');
                t += 4;
            }
            if (neg) v = -v;
            Stat &s = stats[id];
            if (v < s.mn) s.mn = v;
            if (v > s.mx) s.mx = v;
            s.sum += v;
            ++s.count;
            p = t + 1;
        }
    }
};

static inline void append_tenths(std::string &out, int64_t v) {
    if (v < 0) { out.push_back('-'); v = -v; }
    out += std::to_string(v / 10);
    out.push_back('.');
    out.push_back(static_cast<char>('0' + v % 10));
}

int main(int argc, char **argv) {
    if (argc != 2) return 2;
    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) return 2;
    struct stat st;
    if (fstat(fd, &st) != 0) return 2;
    size_t size = static_cast<size_t>(st.st_size);
    size_t page = static_cast<size_t>(sysconf(_SC_PAGESIZE));
    size_t file_map_len = (size + page - 1) & ~(page - 1);
    size_t map_total = file_map_len + page;
    void *mapping_base = mmap(nullptr, map_total, PROT_NONE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mapping_base == MAP_FAILED) { close(fd); return 2; }
    const char *data = static_cast<const char *>(mmap(mapping_base, file_map_len, PROT_READ,
                                                       MAP_PRIVATE | MAP_FIXED, fd, 0));
    if (data == MAP_FAILED) { munmap(mapping_base, map_total); close(fd); return 2; }
    void *padding = mmap(static_cast<char *>(mapping_base) + file_map_len, page, PROT_READ,
                         MAP_PRIVATE | MAP_ANONYMOUS | MAP_FIXED, -1, 0);
    close(fd);
    if (padding == MAP_FAILED) { munmap(mapping_base, map_total); return 2; }

    for (unsigned i = 0; i < NST; ++i) station_lengths[i] = std::strlen(station_names[i]);
    struct Group {
        uint32_t key;
        uint16_t count;
        uint16_t ids[NST];
    };
    std::vector<Group> groups;
    groups.reserve(NST);
    for (unsigned i = 0; i < NST; ++i) {
        size_t n = station_lengths[i];
        uint32_t key = prefix_key(station_names[i], n);
        unsigned g = 0;
        while (g < groups.size() && groups[g].key != key) ++g;
        if (g == groups.size()) {
            Group x{};
            x.key = key;
            groups.push_back(x);
        }
        groups[g].ids[groups[g].count++] = i;
    }
    std::vector<std::vector<unsigned>> buckets(512);
    for (unsigned g = 0; g < groups.size(); ++g)
        buckets[groups[g].key & 511u].push_back(g);
    std::vector<unsigned> bucket_order(512);
    for (unsigned b = 0; b < 512; ++b) bucket_order[b] = b;
    std::sort(bucket_order.begin(), bucket_order.end(), [&](unsigned a, unsigned b) {
        return buckets[a].size() > buckets[b].size();
    });
    bool used[1024] = {};
    unsigned prefix_offset = 0;
    for (unsigned b : bucket_order) {
        if (buckets[b].empty()) continue;
        unsigned displacement = 0;
        std::vector<unsigned> positions(buckets[b].size());
        for (;; ++displacement) {
            bool okay = true;
            for (unsigned j = 0; j < buckets[b].size(); ++j) {
                uint32_t key = groups[buckets[b][j]].key;
                unsigned pos = (((key * 2344817613u) >> 22) + displacement) & 1023u;
                positions[j] = pos;
                if (used[pos]) { okay = false; break; }
                for (unsigned k = 0; k < j; ++k)
                    if (positions[k] == pos) { okay = false; break; }
                if (!okay) break;
            }
            if (okay) break;
        }
        ph_disp[b] = static_cast<uint8_t>(displacement);
        for (unsigned j = 0; j < buckets[b].size(); ++j) {
            unsigned pos = positions[j];
            used[pos] = true;
            const Group &g = groups[buckets[b][j]];
            uint16_t start = (g.count == 1) ? g.ids[0] : static_cast<uint16_t>(prefix_offset);
            ph_start[pos] = start;
            ph_count[pos] = static_cast<uint8_t>(g.count);
            if (g.count != 1)
                for (unsigned k = 0; k < g.count; ++k) prefix_ids[prefix_offset++] = g.ids[k];
        }
    }

    constexpr unsigned T = NTHREADS;
    std::vector<size_t> bounds(T + 1);
    bounds[0] = 0;
    bounds[T] = size;
    for (unsigned i = 1; i < T; ++i) {
        size_t b = size * i / T;
        while (b < size && data[b - 1] != '\n') ++b;
        bounds[i] = b;
    }
    std::vector<Worker> workers;
    workers.reserve(T);
    for (unsigned i = 0; i < T; ++i)
        workers.emplace_back(data + bounds[i], data + bounds[i + 1]);
    std::vector<std::thread> threads;
    threads.reserve(T);
    for (unsigned i = 0; i < T; ++i) {
        threads.emplace_back(std::ref(workers[i]));
        cpu_set_t cpus;
        CPU_ZERO(&cpus);
        CPU_SET(i, &cpus);
        pthread_setaffinity_np(threads.back().native_handle(), sizeof(cpus), &cpus);
    }
    for (std::thread &t : threads) t.join();

    std::vector<Stat> all(NST);
    for (Stat &s : all) { s.mn = 1000; s.mx = -1000; s.sum = 0; s.count = 0; }
    for (const Worker &w : workers) {
        for (int i = 0; i < NST; ++i) {
            const Stat &a = w.stats[i];
            Stat &s = all[i];
            if (a.count) {
                if (a.mn < s.mn) s.mn = a.mn;
                if (a.mx > s.mx) s.mx = a.mx;
                s.sum += a.sum;
                s.count += a.count;
            }
        }
    }

    std::vector<int> order(NST);
    for (int i = 0; i < NST; ++i) order[i] = i;
    std::sort(order.begin(), order.end(), [](int a, int b) {
        return std::strcmp(station_names[a], station_names[b]) < 0;
    });
    std::string out;
    out.reserve(18000);
    out.push_back('{');
    for (int k = 0; k < NST; ++k) {
        if (k) out += ", ";
        int i = order[k];
        out += station_names[i];
        out.push_back('=');
        append_tenths(out, all[i].mn);
        out.push_back('/');
        int64_t mean;
        if (all[i].sum >= 0)
            mean = (all[i].sum + static_cast<int64_t>(all[i].count) / 2) / static_cast<int64_t>(all[i].count);
        else
            mean = -((-all[i].sum + static_cast<int64_t>(all[i].count) / 2) / static_cast<int64_t>(all[i].count));
        append_tenths(out, mean);
        out.push_back('/');
        append_tenths(out, all[i].mx);
    }
    out.push_back('}');
    size_t written = 0;
    while (written < out.size()) {
        ssize_t n = write(STDOUT_FILENO, out.data() + written, out.size() - written);
        if (n <= 0) break;
        written += static_cast<size_t>(n);
    }
    munmap(mapping_base, map_total);
    return written == out.size() ? 0 : 2;
}

